UPDATE companies SET description='Switch Components, Inc. (SCI) is headquartered in El Cajon, California. The company was established in 2018 as an independent component division of Triad Partners, LLC, after its switch products had been manufactured and sold through sister divisions OptiFuse and Vortex Technologies.

SCI supplies AC and DC switch products including rocker, toggle, and pushbutton switches, battery disconnects, trailer connectors, USB charging ports, and relays. Production runs on automated lines featuring continuous table presses, robotic plastic injection and insertion molding, CNC machining, laser marking, and vision inspection. Manufacturing takes place at facilities in Tainan City, Taiwan, and Semarang, Indonesia.

The company serves the transportation, electrical, and electronic markets, with a focus on automotive, heavy-duty, marine, and recreational vehicle applications.

SCI emphasizes its patented illuminated and non-illuminated switch designs, a Total Quality Management approach, and compliance with UL, SAE, ABYC ignition-protected standards, RoHS, REACH, conflict-mineral regulations, and California Proposition 65. The firm states that trust, transparency, and customer service form the basis of its relationships.', certifications=ARRAY['ISO 9001:2002','ISO 14000:2004','TS16949:2002','UL listed/recognized','SAE standards compliance','ABYC ignition protected standards','RoHS directive compliance','REACH regulation compliance','California Proposition 65 compliance']::text[], profile='{"capabilities": ["Rocker switch manufacturing", "Toggle switch manufacturing", "Pushbutton switch manufacturing", "Battery disconnect switch manufacturing", "Trailer connector manufacturing", "USB charging port manufacturing", "Relay manufacturing", "Automated assembly", "Plastic injection molding", "Insertion molding", "CNC machining", "Laser marking", "Vision inspection", "Custom component design", "Total Quality Management (TQM)", "Compliance testing (UL, SAE, ABYC)"], "industries": ["Automotive", "Heavy-duty", "Marine", "Recreational Vehicle (RV)", "Transportation", "Electrical", "Electronic"], "materials": [], "equipment": ["Continuous table presses", "Robotic plastic injection molding machines", "Insertion molding machines", "CNC machining centers", "Laser marking systems", "Vision inspection equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Patented illuminated and non-illuminated switch designs", "Automated production line with robotic injection molding and vision inspection", "Facilities certified to ISO 9001:2002, ISO 14000:2004, and TS16949:2002", "Compliance with SAE, ABYC, UL, RoHS, REACH, conflict minerals, and Proposition 65", "Custom-made components for individual application needs"], "facts_used": ["Headquarters in El Cajon, CA -> db", "Founded 2018 as division of Triad Partners, LLC -> /about-us", "Prior produ