UPDATE companies SET description='TDE Fabrication operates from Lakeland, Minnesota, near the Twin Cities metropolitan area. Tange earned a bachelor''s degree in mechanical engineering from UW–Milwaukee and developed a passion for metalworking and product invention, while Liedtke studied engineering at UW–Platteville before building a career in customer service and sales.

The shop produces custom architectural metalwork for residential and commercial projects across the Midwest. Its portfolio includes floating staircases, interior and exterior railings, statement fireplace surrounds and mantels, pergolas and outdoor shade structures, and decorative metal panels. The team handles design renderings, site measurements, in-house fabrication, and final installation, offering a seamless process from concept to completion.

TDE Fabrication serves home builders, designers, architects, and general contractors throughout the Twin Cities region, including communities such as Minnetonka, Chanhassen, Stillwater, Wayzata, Edina, and Shakopee. The company collaborates with these professionals to deliver structural and decorative metal elements that integrate with broader building projects.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom metal fabrication", "Architectural metalwork", "Custom staircase design and fabrication", "Railing and guardrail fabrication", "Fireplace surround and mantel fabrication", "Pergola and outdoor structure fabrication", "Decorative metalwork", "Design and engineering", "Site measurement and layout", "In-house fabrication", "Installation services"], "industries": ["Residential construction", "Commercial construction", "Architecture", "Interior design", "Home building", "General contracting"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom designs tailored to each project''s style, space, and functional needs", "Advanced fabrication techniques paired with artisan-level attention to detail", "Collaborative process with builders, designers, and contractors from concept to installation", "Premium metals and finishes selected for lasting beauty and performance"], "facts_used": ["Headquarters in Lakeland, Minnesota -> db", "Founders Andrew Tange and Jake Liedtke -> /about", "Andrew Tange mechanical engineering degree UW-Milwaukee, invented RecRamp -> /about", "Jake Liedtke engineering UW-Platteville, customer service background -> /about", "Custom metal railings, fireplaces, staircases, pergolas, decorative metalwork -> /", "Services: custom floating staircases, railings & guardrails, statement fireplaces, pergolas & outdoor structures, exterior architectural features -> /services", "Process: design renderings, site measurements, in-house fabrication, installation -> /", "Industries: home builders, designers, architects, contractors -> /services", "Service areas: Minnetonka, Chanhassen, Stillwater, Wayzata, Edina, Shakopee -> /", "Differentiators: custom designs, unmatched craftsmanship, collaborative process, premium materials -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "TDE Fabrication is a premier custom metalworking shop based near the Twin Cities", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tde-fab' AND approved AND profile IS NULL;
UPDATE companies SET description='TKH Woodworking operates from Leonard, Michigan, where owner Tim Monkevich opened the shop after a decade of woodworking passion. The business is family-owned and run as a sole proprietorship, with Monkevich handling every project personally.

The shop produces custom cutting boards, handcrafted furniture, cabinetry, bathroom vanities, mudroom benches, and bookshelves. All pieces are built from solid hardwood using traditional joinery — drawers feature dovetail construction — and are assembled with durable glues. The operation is a one-person workshop, so each item receives hands-on attention from design through final finish.

Customers are primarily homeowners seeking personalized pieces for their residences, along with gift buyers looking for custom cutting boards. Projects range from kitchen and bathroom cabinetry to one-of-a-kind furniture built to fit specific spaces and styles.

Monkevich emphasizes a direct, one-on-one experience grounded in honesty, clear communication, and respect. He describes himself as a perfectionist who aims to make every piece last a lifetime, differentiating the shop through personal service and a commitment to quality materials and joinery.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cutting board fabrication", "Handcrafted furniture making", "Custom cabinetry and vanity construction", "Mudroom bench building", "Bookshelf fabrication", "Dovetail joinery", "Hardwood gluing and assembly"], "industries": ["Residential construction", "Home furnishings", "Cabinetry", "Giftware", "Woodworking"], "materials": ["Hardwood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["One-on-one personalized service from owner Tim Monkevich", "Family-owned and operated with hands-on craftsmanship", "Dovetail joinery on all drawers", "All pieces made from solid hardwood", "Commitment to honesty, clear communication, and respect"], "facts_used": ["Location: Leonard, Michigan -> /", "Owner: Tim Monkevich -> /", "Family-owned and operated -> /", "Products: custom cutting boards, furniture, cabinetry, vanities, mudroom benches, bookshelves -> /", "Processes: dovetail joinery, hardwood gluing -> /", "Materials: hardwood -> /", "Scale: sole proprietor, one-person workshop -> /", "Differentiators: personalized one-on-one service, honesty, clear communication, respect, perfectionist approach -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "I specialize in custom cutting boards, handcrafted furniture, cabinetry, and vanities \u2014 all built with care, precision, and durable materials. All products are made with hardwood and securely glued. Drawers are made with dovetails.", "founded_year": "", "employee_count": "1", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='tkh-woodworking' AND approved AND profile IS NULL;
UPDATE companies SET description='TREIF USA Inc, with its website at marel.com, is headquartered in Shelton, Connecticut. The company operates as JBT Marel, a global leader in advanced automation for the food and beverage industry.

JBT Marel designs and delivers a comprehensive portfolio that spans high-performing standalone machines to fully integrated, end-to-end processing lines. Its equipment solutions cover primary processing, further processing, refrigeration, and end-of-line packaging across protein, produce, and plant-based categories. Complementing the hardware, the company provides purpose-built food processing software that integrates machine, process, and business data to enable real-time insights, traceability compliance, and preventative maintenance. A global service network — 133 locations across 29 countries — offers lifetime support through service agreements, spare parts, and on-site expertise, anchored by Customer Technology Centers such as the Lakeland Customer Innovation Center where processors can trial technologies like the Flip & Wash bin washer.

The company serves a broad spectrum of food and beverage sectors, including poultry, meat, fish and seafood, prepared foods, ready meals, beverages and juices, fruit and vegetables, plant-based products, dairy and cheese, pet food, material handling automation, pharmaceuticals and nutraceuticals, and water treatment. Notable references include the adoption of Townsend skinners as a standard in the U.S. meat industry and a long-standing partnership with Marlow Foods for plant-based production.

JBT Marel positions its differentiation on the seamless integration of equipment, software, and lifetime service to help customers produce the most value from the least resources. Its automation strategy addresses labor shortages while improving food safety, and its sustainability focus targets energy and water savings, waste reduction, and better raw-material utilization. The firm emphasizes co-creation with customers through its regional technology centers to develop tailored solutions.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Integrated equipment solutions (standalone to full lines)", "Food processing software (traceability, analytics, preventative maintenance)", "Lifetime service support (agreements, spare parts, on-site expertise)", "Process automation for labor reduction and food safety", "Preventative maintenance via equipment connectivity", "Yield improvement and waste reduction", "Resource utilization optimization", "Food quality and safety assurance", "Equipment performance and uptime optimization", "Equipment lifetime extension", "Energy efficiency solutions", "Water conservation systems", "Packaging waste reduction", "Raw material utilization improvement", "Food preservation technologies", "Customer Technology Centers for co-creation and trials"], "industries": ["Poultry", "Meat", "Fish and seafood", "Prepared foods", "Ready meals", "Beverages and juices", "Fruit and vegetables", "Plant-based products", "Dairy and cheese", "Pet food", "Material handling automation", "Pharmaceuticals and nutraceuticals", "Water treatment"], "materials": [], "equipment": ["Townsend skinners", "Flip & Wash bin washer", "Hi2FLex", "Proseal tray-sealing systems", "AXIN Solutions"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["133 locations across 29 countries providing local sales and service", "Lifetime service support maximizing uptime and equipment longevity", "Purpose-built food processing software for data-driven optimization", "Leader in process automation to address labor shortages", "Customer Technology Centers for hands-on co-creation and trials"], "facts_used": ["Company name: TREIF USA Inc -> db", "Website: https://marel.com/en/ -> db", "Headquarters: Shelton, Connecticut -> db", "JBT Marel is a global leader in advanced automation for food and beverage industry -> /", "Offers integrated equipment, software, and services -> /about-us", "133 locations across 29 countries -> /", "Industries served: poultry, meat, fish and seafood, prepared foods, ready meals, beverages and juices, fruit and vegetables, plant-based products, dairy and cheese, pet food, material handling automation, pharmaceuticals and nutraceuticals, water treatment -> /", "Equipment examples: Townsend skinners, Flip & Wash bin washer, Hi2FLex, Proseal tray-sealing, AXIN Solutions -> /", "Lakeland Customer Innovation Center -> /", "Publicly traded on NYSE and Nasdaq Iceland: JBTM -> /", "Sustainability report 2025 -> /", "Service offerings: service agreements, spare parts, preventative maintenance -> /", "Software for traceability compliance, data-driven decisions -> /", "Automation to address labor shortages -> /about-us", "Focus on energy/water savings, waste reduction -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "JBT Marel is a global leader in advanced automation for the food and beverage industry. Our equipment solutions range from high-performing standalone machines to fully integrated, end-to-end processing lines.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='treif-usa-inc' AND approved AND profile IS NULL;
